<?php
namespace App\Http\Controllers\Api\Hr;
use App\Http\Controllers\Controller;
use App\Services\Hr\Attendance\AttendanceIngestionService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
class AttendanceIngestionController extends Controller{public function __invoke(Request$request,AttendanceIngestionService$service):JsonResponse{$headers=['connector_key'=>(string)$request->header('X-Connector-Key'),'request_id'=>(string)$request->header('X-Request-Id'),'nonce'=>(string)$request->header('X-Nonce'),'signed_at'=>(string)$request->header('X-Signed-At'),'signature'=>(string)$request->header('X-Signature')];validator($headers,['connector_key'=>'required|string|max:100','request_id'=>'required|string|max:160','nonce'=>'required|string|max:160','signed_at'=>'required|date','signature'=>'required|string|size:64'])->validate();$data=$request->validate(['events'=>['present','array','max:1000'],'events.*.provider_event_id'=>['required','string','max:200'],'events.*.device_serial'=>['required','string','max:160'],'events.*.provider_person_id'=>['required','string','max:160'],'events.*.employee_number'=>['nullable','string','max:100'],'events.*.occurred_at'=>['required','date'],'events.*.source_timezone'=>['required','timezone'],'events.*.source_utc_offset_minutes'=>['required','integer','between:-840,840'],'events.*.event_kind'=>['required',Rule::in(['punch','door_event','enrollment','heartbeat'])],'events.*.direction'=>['nullable',Rule::in(['in','out','unknown'])],'events.*.authentication_method'=>['nullable','string','max:40'],'events.*.verification_result'=>['nullable','string','max:30']]);return response()->json(['status'=>'success','data'=>$service->ingest($headers,$request->getContent(),$data['events'],$request->ip())],202);}}
